-- Runs after real canonical lifecycle assertions, in their disposable local transaction.
RESET ROLE;
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000001',true),set_config('test.workspace','20000000-0000-0000-0000-000000000001',true),set_config('test.admin','true',true);
UPDATE client_contact_methods SET value='client@example.test' WHERE id='80000000-0000-0000-0000-000000000001';
CREATE FUNCTION proof_preferences(op integer,version bigint,patch jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql AS $$
 SELECT execute_sales_invoice_command('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001',('70000000-0000-0000-0000-'||lpad(op::text,12,'0'))::uuid,
 jsonb_build_object('action','invoice.settings_update','expected_version',version,'settings','{"prefix":"INV-","next_number":1,"padding":5,"template":"classic","accent":"#4931ac","logo_data_uri":null,"footer":"","payment_instructions":""}'::jsonb||patch),proof_governance('invoice.settings_update','sales_update_invoice_settings'))
$$;
GRANT EXECUTE ON FUNCTION proof_preferences(integer,bigint,jsonb) TO service_role;
SET ROLE authenticated;
SELECT proof_assert(read_sales_invoice_preferences('20000000-0000-0000-0000-000000000001')->>'version'='0','absent preferences default version zero');
SELECT proof_assert((SELECT mode='confirm' AND is_default FROM list_tool_autonomy('20000000-0000-0000-0000-000000000001') WHERE tool_key='sales_update_invoice_settings'),'settings catalogue confirm default');
SELECT proof_assert((SELECT count(*)=3 FROM list_tool_autonomy('20000000-0000-0000-0000-000000000001') WHERE tool_key IN ('studio_image_publish','sales_stage_collection_import','ghl_run_action')),'live Studio Collections and prior catalogue preserved');
SELECT proof_denied($q$SELECT read_sales_invoice_preferences('20000000-0000-0000-0000-000000000002')$q$,'42501','foreign workspace prefs refused');
SELECT proof_denied($q$SELECT proof_preferences(501,0)$q$,'42501','authenticated settings write bypass denied');
SELECT proof_denied($q$UPDATE tenants SET brand='{"invoice_preferences":{}}' WHERE id='20000000-0000-0000-0000-000000000001'$q$,'42501','direct brand prefs change denied');
SELECT proof_denied($q$SELECT set_tenant_brand('20000000-0000-0000-0000-000000000001','{"invoice_preferences":{}}')$q$,'42501','generic brand setter cannot change preferences');
RESET ROLE;
CREATE TEMP TABLE original_document AS SELECT billing_document doc FROM paige_invoices WHERE id='60000000-0000-0000-0000-000000000091';
SET ROLE service_role;
CREATE TEMP TABLE preferences_result AS SELECT proof_preferences(501,0,'{"template":"modern","footer":"Thanks\nFor your business","payment_instructions":"Wire reference invoice"}') result;
SELECT proof_assert((SELECT result#>>'{preferences,version}' FROM preferences_result)='1','governed settings persist with canonical readback');
SELECT proof_assert((SELECT result FROM preferences_result)=proof_preferences(501,0,'{"template":"modern","footer":"Thanks\nFor your business","payment_instructions":"Wire reference invoice"}'),'settings exact historical replay');
SELECT proof_denied($q$SELECT proof_preferences(501,0,'{"template":"service"}')$q$,'22023','operation reuse different settings refused');
SELECT proof_denied($q$SELECT proof_preferences(502,0)$q$,'40001','stale settings version refused');
SELECT proof_denied($q$SELECT proof_preferences(502,1,'{"next_number":1.5}')$q$,'22023','fractional numbering refused');
SELECT proof_denied($q$SELECT proof_preferences(502,1,'{"prefix":"<script>"}')$q$,'22023','unsafe prefix refused');
SELECT proof_denied($q$SELECT proof_preferences(502,1,'{"logo_data_uri":"https://example.test/logo.png"}')$q$,'22023','remote logo refused');
SELECT proof_denied($q$SELECT proof_preferences(502,1,'{"logo_data_uri":"data:image/png;base64,PHN2Zz4="}')$q$,'22023','mislabeled image bytes refused');
SELECT proof_denied($q$SELECT proof_preferences(502,1,'{"unexpected":true}')$q$,'22023','extra preferences key refused');
SELECT proof_denied($q$SELECT proof_preferences(502,1,jsonb_build_object('logo_data_uri','data:image/png;base64,'||repeat('A',175000)))$q$,'22023','oversized embedded logo refused');
RESET ROLE;
SELECT proof_assert((SELECT count(*) FROM paige_workspace_events WHERE source_id='70000000-0000-0000-0000-000000000501')=1,'settings one canonical Rail receipt');
SELECT proof_assert((SELECT billing_document FROM paige_invoices WHERE id='60000000-0000-0000-0000-000000000091')=(SELECT doc FROM original_document),'old issued document untouched');
SET ROLE authenticated;
SELECT proof_assert(set_tenant_brand('20000000-0000-0000-0000-000000000001',jsonb_build_object('support_email','business@example.test','business_phone','+15555550123','website','https://example.test','invoice_preferences',(SELECT brand->'invoice_preferences' FROM tenants WHERE id='20000000-0000-0000-0000-000000000001')))#>>'{invoice_preferences,version}'='1','other brand edits preserve unchanged full preferences');
-- Real draft persistence; custom immutable input used by later concurrent publications.
SELECT save_sales_billing_draft('20000000-0000-0000-0000-000000000001',('60000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,0,('71000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,
 (SELECT draft FROM snapshot_input)||'{"kind":"one_time","deposit_basis_points":null,"agreement_id":null,"items":[{"price_id":null,"item":"Custom service","unit_minor":1000,"quantity":1}]}') FROM generate_series(501,506) i;
SET ROLE service_role;
CREATE TEMP TABLE appearance_result AS SELECT execute_sales_invoice_command('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000503','{"action":"invoice.publish","invoice_id":"60000000-0000-0000-0000-000000000501","expected_version":1,"template":"service"}',proof_governance('invoice.publish','sales_publish_invoice')) result;
SELECT proof_assert((SELECT result#>>'{row,invoice_number}' FROM appearance_result)='INV-00001','publication returns allocated tenant number');
SELECT proof_assert((SELECT result#>>'{row,document,renderer_version}' FROM appearance_result)='paige-invoice-html-v2','publication returns frozen v2 renderer');
SELECT proof_assert((SELECT result#>>'{row,document,presentation,template}' FROM appearance_result)='service','explicit template freezes publication override');
SELECT proof_assert((SELECT result#>>'{row,document,presentation,issuer_email}' FROM appearance_result)='business@example.test','canonical issuer contact captured');
SELECT proof_assert((SELECT result FROM appearance_result)=execute_sales_invoice_command('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000503','{"action":"invoice.publish","invoice_id":"60000000-0000-0000-0000-000000000501","expected_version":1,"template":"service"}',proof_governance('invoice.publish','sales_publish_invoice')),'publication replay does not allocate again');
SELECT proof_preferences(504,2,'{"template":"classic","next_number":1}');
SELECT proof_assert((SELECT result FROM preferences_result)=proof_preferences(501,0,'{"template":"modern","footer":"Thanks\nFor your business","payment_instructions":"Wire reference invoice"}'),'settings original replay survives subsequent publication and newer preferences');
SELECT proof_denied($q$SELECT execute_sales_invoice_command('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000505','{"action":"invoice.publish","invoice_id":"60000000-0000-0000-0000-000000000502","expected_version":1}',proof_governance('invoice.publish','sales_publish_invoice'))$q$,'23505','existing local invoice number collision refuses atomically');
RESET ROLE;
SELECT proof_assert((SELECT status='draft' FROM paige_invoices WHERE id='60000000-0000-0000-0000-000000000502'),'collision preserves unissued draft');
SELECT proof_assert((SELECT brand#>>'{invoice_preferences,settings,next_number}' FROM tenants WHERE id='20000000-0000-0000-0000-000000000001')='1','collision does not consume number');
SELECT proof_assert((SELECT billing_document#>>'{presentation,template}' FROM paige_invoices WHERE id='60000000-0000-0000-0000-000000000501')='service','later preferences do not rewrite issued template');
SELECT proof_assert((SELECT billing_document_digest=encode(extensions.digest(convert_to(billing_document::text,'UTF8'),'sha256'),'hex') FROM paige_invoices WHERE id='60000000-0000-0000-0000-000000000501'),'digest hashes trigger-updated frozen facts');
INSERT INTO paige_invoices(id,tenant_id,contact_id,invoice_number,amount_total_cents) VALUES('60000000-0000-0000-0000-000000000599','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','LEG-00001',42);
SAVEPOINT legacy_number;
SET ROLE service_role;
SELECT proof_preferences(596,3,'{"prefix":"LEG-"}');
SELECT proof_denied($q$SELECT execute_sales_invoice_command('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000597','{"action":"invoice.publish","invoice_id":"60000000-0000-0000-0000-000000000502","expected_version":1}',proof_governance('invoice.publish','sales_publish_invoice'))$q$,'23505','legacy human number collision refuses publication');
RESET ROLE;
SELECT proof_assert((SELECT amount_total_cents=42 AND billing_draft_version IS NULL AND invoice_number='LEG-00001' FROM paige_invoices WHERE id='60000000-0000-0000-0000-000000000599'),'legacy duplicate number row remains unchanged');
ROLLBACK TO legacy_number;
SELECT proof_denied($q$UPDATE paige_invoices SET billing_document=jsonb_set(billing_document,'{presentation,template}','"classic"') WHERE id='60000000-0000-0000-0000-000000000501'$q$,'42501','issued presentation immutable even privileged update');
SAVEPOINT valid_logo;
SET ROLE service_role;
SELECT proof_assert(proof_preferences(590,3,'{"logo_data_uri":"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aT28AAAAASUVORK5CYII="}')#>>'{preferences,settings,logo_data_uri}' LIKE 'data:image/png;base64,%','bounded PNG persists through governed settings');
ROLLBACK TO valid_logo;
RESET ROLE;
CREATE FUNCTION proof_invoice_rail_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.source_id='70000000-0000-0000-0000-000000000595' THEN RAISE EXCEPTION 'Injected Rail failure' USING ERRCODE='55000'; END IF; RETURN NEW; END $$;
CREATE TRIGGER proof_invoice_rail_failure BEFORE INSERT ON paige_workspace_events FOR EACH ROW EXECUTE FUNCTION proof_invoice_rail_failure();
SET ROLE service_role;
SELECT proof_denied($q$SELECT proof_preferences(595,3,'{"next_number":20}')$q$,'55000','settings receipt failure rolls back settings write');
RESET ROLE;
SELECT proof_assert((SELECT brand#>>'{invoice_preferences,version}' FROM tenants WHERE id='20000000-0000-0000-0000-000000000001')='3' AND NOT EXISTS(SELECT 1 FROM paige_invoice_operations WHERE id='70000000-0000-0000-0000-000000000595'),'failed settings receipt leaves no result or new version');
DROP TRIGGER proof_invoice_rail_failure ON paige_workspace_events;
SELECT proof_assert(_workspace_event_display('capability_run','capability_succeeded','sales_update_invoice_settings')->>'title'='Updated invoice appearance and numbering','settings named canonical Rail projection');
-- Cross-tenant equal human numbers are legal; identity remains UUID + tenant.
