SET ROLE authenticated;
SELECT save_sales_billing_draft('20000000-0000-0000-0000-000000000002','60000000-0000-0000-0000-000000000507',0,'71000000-0000-0000-0000-000000000507',(SELECT draft FROM snapshot_input)||'{"client_id":"30000000-0000-0000-0000-000000000002","kind":"one_time","deposit_basis_points":null,"agreement_id":null,"items":[{"price_id":null,"item":"Custom service","unit_minor":1000,"quantity":1}],"recipient_email":"other@example.test","email_source_method_id":"80000000-0000-0000-0000-000000000002","recipient_phone":null,"phone_source_method_id":null}');
SET ROLE service_role;
SELECT execute_sales_invoice_command('10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002','70000000-0000-0000-0000-000000000507','{"action":"invoice.publish","invoice_id":"60000000-0000-0000-0000-000000000507","expected_version":1}',jsonb_build_object('actor_user_id','10000000-0000-0000-0000-000000000002','tenant_id','20000000-0000-0000-0000-000000000002','action','invoice.publish','tool','sales_publish_invoice','approval_channel','operator_card','approved_fingerprint','0123456789abcdef','decision_receipt_recorded',true));
